	@ParameterizedTest
	@CsvSource({ "false,0", "false,1", "false,2", "true,0", "true,1", "true,2" })
	void semiAntiCorrelationSeesAliasAboveWholeConjunctiveSurface(boolean anti, int algorithm) throws Exception {
		Extension whole = alias(new Join(statement("x", FIRST, "y"), statement("y", SECOND, "z")), "z", 1);
		Exists exists = new Exists(statement("fanout1", THIRD, "t"));
		var call = PackedCostTestSupport.filterOperator(defaultGraph(),
				new Filter(whole, anti ? new Not(exists) : exists), 17.0d);
		int relation = 0;
		for (int candidate = 1; candidate <= call.query().relationCount(); candidate++) {
			if ((anti ? call.query().isAntiJoin(candidate) : call.query().isSemiJoin(candidate))
					&& call.query().semiAntiAlgorithm(candidate) == algorithm) {
				relation = candidate;
				break;
			}
		}
		assertTrue(relation > 0, "the real packed rewrite must retain the requested semi/anti implementation");
		try (Fixture fixture = new Fixture(); PackedCostSession session = fixture.model.openSession(call.query())) {
			when(fixture.view.estimateProjectedDistinct(any(), anyInt())).thenReturn(10.0d);
			int input = call.query().childRelationId(relation, 0);
			PackedCostEstimate selected = price(session, call.query(), null, input);
			PackedCostEstimate output = new PackedCostEstimate();
			output.setContextualRows(anti ? 13.0d : 4.0d, 17.0d);
			PackedCostContext context = PackedCostTestSupport.operatorInputs(new int[] { input },
					selected.outputRows(), selected.evidenceStateId(), selected.outputRows(), 100.0d,
					selected.evidenceStateId(), 0);
			clearInvocations(fixture.view);
			session.refineOperator(relation, context, output);
			assertEquals("mapped-omni-correlated-semi-join",
					output.plannedStringMetric("plannedSemiAntiSelectivitySource"),
					"the alias component is represented inside the complete multi-occurrence outer surface");
			assertTrue(mockingDetails(fixture.view).getInvocations()
					.stream()
					.anyMatch(invocation -> invocation.getMethod().getName().equals("estimateSubgraph")
							&& ((FrontierJoinProgram) invocation.getArgument(0)).patternCount() == 3));
		}
	}

