	@Test
	void repeatedWholeBagCannotBorrowOneDeduplicatedStatisticalOccurrence() {
		Extension alias = alias(statement("page", FIRST, "event"), "event", 1);
		var call = PackedCostTestSupport.unaryOperator(defaultGraph(), alias);
		PackedCostEstimate output = new PackedCostEstimate();
		output.setRows(100.0d, 100.0d);
		LmdbSemanticPopulationProof proofs = new LmdbSemanticPopulationProof(call.query(), 32);
		int whole = proofs.isolated(call.operatorRelationId(), call.emptyContext(), output);
		int repeated = proofs.join(whole, whole);
		assertTrue(whole > 0);
		assertTrue(repeated > 0);
		assertFalse(proofs.describes(repeated, new int[] { call.operatorRelationId() }),
				"a Set containing one root cannot describe two occurrences of that whole bag");
		assertTrue(proofs.describes(repeated,
				new int[] { call.operatorRelationId(), call.operatorRelationId() }),
				"the proof retains both occurrences without relying on encoder deduplication assumptions");
	}

	@ParameterizedTest
	@ValueSource(strings = { "filter", "optional", "union", "minus", "distinct", "reduced", "slice", "group",
			"projection", "graph", "custom" })
	void unsupportedWholeOperatorsStayOpaque(String operator) throws Exception {
		TupleExpr leaf = statement("page", FIRST, "event");
		TupleExpr other = statement("event", SECOND, "maybe");
		TupleExpr wrapped = switch (operator) {
		case "filter" -> new Filter(leaf, new ValueConstant(VF.createLiteral(true)));
		case "optional" -> new LeftJoin(leaf, other);
		case "union" -> new Union(leaf, other);
		case "minus" -> new Difference(leaf, other);
		case "distinct" -> new Distinct(leaf);
		case "reduced" -> new Reduced(leaf);
		case "slice" -> new Slice(leaf, 0L, 1L);
		case "group" -> new Group(leaf);
		case "projection" -> new Projection(leaf);
		case "graph" -> new Graph(Var.of("graph"), leaf);
		case "custom" -> new TupleFunctionCall();
		default -> throw new AssertionError(operator);
		};
		try (Fixture fixture = new Fixture()) {
			assertNull(LmdbFrontierProbeFactory.joinProgramForLineage(fixture.valueStore,
					List.of(alias(wrapped, "event", 1), statement("fanout1", THIRD, "topic")),
					FrontierLeafProbe.BOTH_PLANES));
		}
	}

